import sys
from fractions import gcd

def solve(a, b):
	if b == 1:
		return 1
	g = gcd(a, b)
	if g == 1:
		return 0
	return solve(a, b // g)
t = int(sys.stdin.readline())
while t > 0:
	t -= 1
	(a, b) = map(int, sys.stdin.readline().split())
	if solve(a, b):
		print('Yes')
	else:
		print('No')
